import type { MetadataRoute } from "next";

// Installable PWA (served at /manifest.webmanifest). Icons are generated by
// scripts/generate-icons.mjs. No service worker: the tracker is live-only and
// must never serve cached location data, and current browsers install without one.
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "Spidey Tracker",
    short_name: "Spidey",
    description: "Temporary, consent-based two-person location sharing on a retro pixel tracker.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    theme_color: "#2f8fce",
    background_color: "#0d2a4d",
    categories: ["navigation", "social", "utilities"],
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icons/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
